-- Shared, atomic rate limiting for the public username sign-in Edge Function.
-- Only service_role may invoke the RPC; callers supply HMACs generated by the
-- server-side function, never raw usernames or client-supplied IP values.
CREATE TABLE public.username_signin_rate_limits (
  bucket_key text PRIMARY KEY,
  window_started_at timestamptz NOT NULL,
  attempt_count integer NOT NULL CHECK (attempt_count > 0),
  blocked_until timestamptz,
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE INDEX username_signin_rate_limits_updated_at_idx
  ON public.username_signin_rate_limits (updated_at);

ALTER TABLE public.username_signin_rate_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.username_signin_rate_limits FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.consume_username_signin_attempt(
  p_ip_key text,
  p_username_key text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_ip_count integer;
  v_ip_blocked_until timestamptz;
  v_pair_count integer;
  v_pair_blocked_until timestamptz;
  v_retry_after integer := 0;
BEGIN
  IF p_ip_key IS NULL OR p_ip_key !~ '^[0-9a-f]{64}$'
     OR p_username_key IS NULL OR p_username_key !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Invalid rate-limit key' USING ERRCODE = '22023';
  END IF;

  -- Opportunistic retention bound: hashes are not kept beyond two days.
  DELETE FROM public.username_signin_rate_limits
  WHERE updated_at < v_now - interval '2 days';

  -- Per-IP bucket: 30 attempts in five minutes, then a 15-minute block.
  INSERT INTO public.username_signin_rate_limits AS current_bucket
    (bucket_key, window_started_at, attempt_count, blocked_until, updated_at)
  VALUES ('ip:' || p_ip_key, v_now, 1, NULL, v_now)
  ON CONFLICT (bucket_key) DO UPDATE SET
    attempt_count = CASE
      WHEN current_bucket.window_started_at <= v_now - interval '5 minutes' THEN 1
      ELSE current_bucket.attempt_count + 1
    END,
    window_started_at = CASE
      WHEN current_bucket.window_started_at <= v_now - interval '5 minutes' THEN v_now
      ELSE current_bucket.window_started_at
    END,
    blocked_until = CASE
      WHEN current_bucket.blocked_until > v_now THEN current_bucket.blocked_until
      WHEN current_bucket.window_started_at <= v_now - interval '5 minutes' THEN NULL
      WHEN current_bucket.attempt_count + 1 > 30 THEN v_now + interval '15 minutes'
      ELSE NULL
    END,
    updated_at = v_now
  RETURNING current_bucket.attempt_count, current_bucket.blocked_until
  INTO v_ip_count, v_ip_blocked_until;

  -- Per-IP + username bucket: five attempts in 15 minutes, then a 15-minute block.
  INSERT INTO public.username_signin_rate_limits AS current_bucket
    (bucket_key, window_started_at, attempt_count, blocked_until, updated_at)
  VALUES ('pair:' || p_ip_key || ':' || p_username_key, v_now, 1, NULL, v_now)
  ON CONFLICT (bucket_key) DO UPDATE SET
    attempt_count = CASE
      WHEN current_bucket.window_started_at <= v_now - interval '15 minutes' THEN 1
      ELSE current_bucket.attempt_count + 1
    END,
    window_started_at = CASE
      WHEN current_bucket.window_started_at <= v_now - interval '15 minutes' THEN v_now
      ELSE current_bucket.window_started_at
    END,
    blocked_until = CASE
      WHEN current_bucket.blocked_until > v_now THEN current_bucket.blocked_until
      WHEN current_bucket.window_started_at <= v_now - interval '15 minutes' THEN NULL
      WHEN current_bucket.attempt_count + 1 > 5 THEN v_now + interval '15 minutes'
      ELSE NULL
    END,
    updated_at = v_now
  RETURNING current_bucket.attempt_count, current_bucket.blocked_until
  INTO v_pair_count, v_pair_blocked_until;

  IF v_ip_blocked_until > v_now THEN
    v_retry_after := greatest(v_retry_after, ceil(extract(epoch FROM (v_ip_blocked_until - v_now)))::integer);
  ELSIF v_ip_count > 30 THEN
    v_retry_after := greatest(v_retry_after, 900);
  END IF;

  IF v_pair_blocked_until > v_now THEN
    v_retry_after := greatest(v_retry_after, ceil(extract(epoch FROM (v_pair_blocked_until - v_now)))::integer);
  ELSIF v_pair_count > 5 THEN
    v_retry_after := greatest(v_retry_after, 900);
  END IF;

  RETURN jsonb_build_object(
    'allowed', v_retry_after = 0,
    'retry_after_seconds', v_retry_after
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.consume_username_signin_attempt(text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.consume_username_signin_attempt(text, text) TO service_role;

DO $verify_username_rate_limit$
BEGIN
  IF has_function_privilege('anon', 'public.consume_username_signin_attempt(text,text)', 'EXECUTE')
     OR has_function_privilege('authenticated', 'public.consume_username_signin_attempt(text,text)', 'EXECUTE')
     OR NOT has_function_privilege('service_role', 'public.consume_username_signin_attempt(text,text)', 'EXECUTE') THEN
    RAISE EXCEPTION 'Username sign-in rate limiter has unsafe function grants';
  END IF;
  IF has_table_privilege('anon', 'public.username_signin_rate_limits', 'SELECT')
     OR has_table_privilege('authenticated', 'public.username_signin_rate_limits', 'SELECT')
     OR has_table_privilege('service_role', 'public.username_signin_rate_limits', 'SELECT') THEN
    RAISE EXCEPTION 'Username sign-in rate-limit state is directly readable by an API role';
  END IF;
END
$verify_username_rate_limit$;

NOTIFY pgrst, 'reload schema';
